 for(unsigned flags=0;flags<256;++flags)for(unsigned entry:{0x3c10u,0x401cu,0x5eeu}){f.prepare(entry,flags);f.word(0xc144,0);f.word(0xc146,0);f.word(0xc1cc,0);f.word(0xc1ce,0);f.byte(0xcd70,0);f.byte(0xcd72,0);f.whole();}
