 for(unsigned gain=0;gain<256;++gain)for(unsigned input=0;input<256;++input){f.prepare(0x1fee,input);f.a->reg32(2)=f.b->reg32(2)=0xc8ae;f.a->reg16(3)=f.b->reg16(3)=0x400;f.a->reg8(6)=f.b->reg8(6)=int8_t(input);f.byte(0xc8ae,128);f.byte(0xc8af,gain);f.whole();}
 for(unsigned centre:{0u,127u,255u})for(unsigned bias:{0u,0x400u})for(unsigned gain:{0u,1u,127u,128u,255u})for(unsigned input:{0u,1u,127u,128u,255u}){f.prepare(0x1fee,input);f.a->reg32(2)=f.b->reg32(2)=0xc8b0;f.a->reg16(3)=f.b->reg16(3)=int16_t(bias);f.a->reg8(6)=f.b->reg8(6)=int8_t(input);f.byte(0xc8b0,centre);f.byte(0xc8b1,gain);f.whole();}
 for(unsigned channel:{0u,0x1cu,0x1du})for(unsigned tail:{0u,0x1feu})for(unsigned input:{0u,127u,255u}){f.prepare(0x5ee,input);f.word(0xc1ce,tail);f.word(0xc1cc,(tail+2)&0x1fe);f.word(0xc1d0+tail,(input<<8)|channel);f.whole();f.prepare(0x401c,input);f.byte(0xcd70,0);f.byte(0xcd72,0);f.word(0xc1ce,tail);f.word(0xc1cc,(tail+2)&0x1fe);f.word(0xc1d0+tail,(input<<8)|channel);f.whole();}
