 uint64_t shorts=0,blocked=0;unsigned calls=0;kstation::FlashCredits cr;using T=kstation::AdcCalibrationTransformTask;for(unsigned input:{0u,127u,128u,255u})for(unsigned gain:{0u,127u,255u}){T t{0xc8ae,uint8_t(input),0x400};while(!t.complete()){auto advance=[&](unsigned b){return t.advanceBefore(b,cr,[&](bool g){++calls;return g?gain:128u;});};shortBudgets(t,cr,calls,shorts,advance);advance(t.nextClocks(cr));}}
